mapper.select:

		where u.del_flag = '0' AND d.DEL_FLAG = 0

			AND u.USER_TYPE = #{userType}


			AND u.user_name like CONCAT(CONCAT('%', #{userName}),'%')


            AND u.nick_name like CONCAT(CONCAT('%', #{nickName}),'%')


			AND u.tenant_id = #{tenantId}


			AND i.enforcement like CONCAT(CONCAT('%', #{enforcement}),'%')


		${dataScope}
        ORDER BY i.create_time DESC


where u.del_flag = '0' AND d.DEL_FLAG = 0
and  u.user_id = #{userId}

${dataScope}

		select i.user_id, i.enforcement, i.adopt ,i.login , i.create_by, i.create_time,i.update_by, i.update_time
        	from sys_enforcement_info i
		where i.user_id = #{userId}

mapper.update:
update sys_enforcement_info
enforcement =#{enforcement}, adopt = #{adopt}, login = #{login}, update_by = #{updateBy}, update_time = now()
where user_id = #{userId}
